CREATE OR REPLACE FUNCTION groups__scd2_close_fn() RETURNS TRIGGER AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('groups:' || NEW.group_id, 0));
  SELECT COALESCE(MIN(valid_from), 'infinity') INTO NEW.valid_to
  FROM groups
  WHERE group_id = NEW.group_id
    AND (valid_from, id) > (NEW.valid_from, NEW.id);
  UPDATE groups SET valid_to = NEW.valid_from
  WHERE group_id = NEW.group_id
    AND (valid_from, id) < (NEW.valid_from, NEW.id)
    AND valid_to > NEW.valid_from;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql

