  PERFORM pg_advisory_xact_lock(hashtextextended('projects:' || NEW.project_id, 0));
  SELECT COALESCE(MIN(valid_from), 'infinity') INTO NEW.valid_to
  FROM projects
  WHERE project_id = NEW.project_id
    AND (valid_from, id) > (NEW.valid_from, NEW.id);
  UPDATE projects SET valid_to = NEW.valid_from
  WHERE project_id = NEW.project_id
    AND (valid_from, id) < (NEW.valid_from, NEW.id)
    AND valid_to > NEW.valid_from;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE TRIGGER projects__scd2_close BEFORE INSERT ON projects
FOR EACH ROW EXECUTE FUNCTION projects__scd2_close_fn()

