  FROM physical_function_runs
  WHERE logical_function_run_id = NEW.logical_function_run_id
    AND (valid_from, id) > (NEW.valid_from, NEW.id);
  UPDATE physical_function_runs SET valid_to = NEW.valid_from
  WHERE logical_function_run_id = NEW.logical_function_run_id
    AND (valid_from, id) < (NEW.valid_from, NEW.id)
