  SELECT COALESCE(MIN(valid_from), 'infinity') INTO NEW.valid_to
  FROM physical_table_data_versions
  WHERE logical_table_data_version_id = NEW.logical_table_data_version_id
    AND (valid_from, id) > (NEW.valid_from, NEW.id)
