CREATE TRIGGER physical_table_data_versions__scd2_settle BEFORE UPDATE OF valid_from ON physical_table_data_versions
FOR EACH ROW WHEN (OLD.valid_to = OLD.valid_from AND NEW.valid_from > OLD.valid_from) EXECUTE FUNCTION physical_table_data_versions__scd2_close_fn()

CREATE OR REPLACE FUNCTION workers__transitions_fn() RETURNS TRIGGER AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND (OLD.worker_type, OLD.status, NEW.status) NOT IN (VALUES ('F', 'RR', 'R'), ('F', 'RR', 'F'), ('F', 'R', 'D'), ('F', 'R', 'F'), ('CT', 'S', 'RR'), ('CT', 'RR', 'R'), ('CT', 'RR', 'F'), ('CT', 'R', 'D'), ('CT', 'R', 'F'), ('CT', 'D', 'R'), ('CT', 'D', 'F'), ('CT', 'F', 'R'), ('CT', 'F', 'D'), ('CT', 'S', 'SP'), ('CT', 'S', 'SPS'), ('CT', 'RR', 'SPS'), ('CT', 'R', 'SPS'), ('CT', 'D', 'SPS'), ('CT', 'F', 'SPS'), ('CT', 'SPS', 'SPR'), ('CT', 'SPS', 'SP'), ('CT', 'SPR', 'SP'), ('ST', 'S', 'RR'), ('ST', 'RR', 'R'), ('ST', 'RR', 'F'), ('ST', 'R', 'D'), ('ST', 'R', 'F'), ('ST', 'D', 'F'), ('ST', 'F', 'R'), ('ST', 'S', 'SP'), ('ST', 'S', 'SPS'), ('ST', 'RR', 'SPS'), ('ST', 'R', 'SPS'), ('ST', 'D', 'SPS'), ('ST', 'F', 'SPS'), ('ST', 'SPS', 'SPR'), ('ST', 'SPS', 'SP'), ('ST', 'SPR', 'SP')) THEN
    RAISE EXCEPTION 'workers.status cannot move from % to %', OLD.status, NEW.status;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE TRIGGER workers__transitions BEFORE UPDATE OF status ON workers
FOR EACH ROW EXECUTE FUNCTION workers__transitions_fn()

CREATE VIEW users__with_names WITH (security_invoker = true) AS SELECT "users".*, COALESCE(created_by_user.name, '[' || users.created_by_id || ']') AS "created_by", COALESCE(modified_by_user.name, '[' || users.modified_by_id || ']') AS "modified_by" FROM "users" LEFT JOIN "users" AS "created_by_user" ON "users"."created_by_id" = "created_by_user"."id" LEFT JOIN "users" AS "modified_by_user" ON "users"."modified_by_id" = "modified_by_user"."id"

CREATE VIEW service_tokens__with_names WITH (security_invoker = true) AS SELECT "service_tokens".*, "users"."name" AS "user_name", "users"."enabled" AS "user_enabled" FROM "service_tokens" JOIN "users" ON "service_tokens"."user_id" = "users"."id"

CREATE VIEW groups__with_names WITH (security_invoker = true) AS SELECT "groups"."id", "groups"."project_id", "groups"."group_id", "groups"."name", "groups"."description", "groups"."system", "groups"."kind", "groups"."valid_from", "groups"."valid_to", "groups"."defined_by_id", COALESCE(defined_by_user.name, '[' || groups.defined_by_id || ']') AS "defined_by" FROM "groups" LEFT JOIN "users" AS "defined_by_user" ON "groups"."defined_by_id" = "defined_by_user"."id"

CREATE VIEW projects__with_names WITH (security_invoker = true) AS SELECT "projects"."id", "projects"."project_id", "projects"."name", "projects"."description", "projects"."base_path", "projects"."valid_from", "projects"."valid_to", "projects"."defined_by_id", COALESCE(defined_by_user.name, '[' || projects.defined_by_id || ']') AS "defined_by" FROM "projects" LEFT JOIN "users" AS "defined_by_user" ON "projects"."defined_by_id" = "defined_by_user"."id"

CREATE VIEW collections__with_names WITH (security_invoker = true) AS SELECT "collections"."id", "collections"."project_id", "collections"."collection_id", "collections"."name", "collections"."description", "collections"."base_path", "collections"."group_id", "collections"."collection_type", "collections"."connection_id", "collections"."valid_from", "collections"."valid_to", "collections"."defined_by_id", COALESCE("collections"."base_path", "last_project"."base_path") AS "effective_base_path", COALESCE((CASE WHEN ("last_project"."valid_to" = ('infinity'::timestamptz)) THEN "last_project"."name" END), '[' || "collections"."project_id" || ']') AS "project", COALESCE(users.name, '[' || collections.defined_by_id || ']') AS "defined_by", COALESCE((CASE WHEN ("last_group"."valid_to" = ('infinity'::timestamptz)) THEN "last_group"."name" END), '[' || "collections"."group_id" || ']') AS "group" FROM "collections" LEFT JOIN "projects" AS "last_project" ON "last_project"."project_id" = "collections"."project_id" AND (NOT EXISTS(SELECT 1 FROM "projects" AS "later" WHERE "later"."project_id" = "last_project"."project_id" AND ("later"."valid_from", "later"."id") > ("last_project"."valid_from", "last_project"."id"))) LEFT JOIN "groups" AS "last_group" ON "last_group"."group_id" = "collections"."group_id" AND (NOT EXISTS(SELECT 1 FROM "groups" AS "later" WHERE "later"."group_id" = "last_group"."group_id" AND ("later"."valid_from", "later"."id") > ("last_group"."valid_from", "last_group"."id"))) LEFT JOIN "users" ON "collections"."defined_by_id" = "users"."id"

CREATE VIEW connection_catalogs__with_names WITH (security_invoker = true) AS SELECT "collections"."connection_id" AS "connection_id", "collections"."project_id" AS "project_id", "collections"."collection_id" AS "collection_id", "connections"."kind" AS "kind", COALESCE("connection_catalogs"."check_status", 'unknown') AS "check_status", "connection_catalogs"."check_error" AS "check_error", "connection_catalogs"."checked_on" AS "checked_on", "connection_catalogs"."schema_hash" AS "schema_hash", COALESCE("connection_catalogs"."entity_count", 0) AS "entity_count", COALESCE("connection_catalogs"."truncated", FALSE) AS "truncated", "connection_catalogs"."metadata_on" AS "metadata_on", COALESCE("connection_catalogs"."metadata_status", 'none') AS "metadata_status", "connection_catalogs"."metadata_error" AS "metadata_error", "connection_catalogs"."last_probe_id" AS "last_probe_id", COALESCE("connection_catalogs"."text_revision", 0) AS "text_revision", "collections"."name" AS "collection", "collections"."description" AS "collection_description", "collections"."collection_type" AS "collection_type", COALESCE((CASE WHEN ("last_project"."valid_to" = ('infinity'::timestamptz)) THEN "last_project"."name" END), '[' || "collections"."project_id" || ']') AS "project" FROM "collections" INNER JOIN "connections" ON "collections"."connection_id" = "connections"."id" LEFT JOIN "projects" AS "last_project" ON "last_project"."project_id" = "collections"."project_id" AND (NOT EXISTS(SELECT 1 FROM "projects" AS "later" WHERE "later"."project_id" = "last_project"."project_id" AND ("later"."valid_from", "later"."id") > ("last_project"."valid_from", "last_project"."id"))) LEFT JOIN "connection_catalogs" ON "collections"."connection_id" = "connection_catalogs"."connection_id" WHERE "collections"."valid_to" = ('infinity'::timestamptz)

CREATE VIEW roles__with_names WITH (security_invoker = true) AS SELECT "roles"."id", "roles"."name", "roles"."description", "roles"."created_on", "roles"."created_by_id", COALESCE(created_by_user.name, '[' || roles.created_by_id || ']') AS "created_by", "roles"."modified_on", "roles"."modified_by_id", COALESCE(modified_by_user.name, '[' || roles.modified_by_id || ']') AS "modified_by", "roles"."kind", "roles"."project_id", "roles"."fixed" FROM "roles" LEFT JOIN "users" AS "created_by_user" ON "roles"."created_by_id" = "created_by_user"."id" LEFT JOIN "users" AS "modified_by_user" ON "roles"."modified_by_id" = "modified_by_user"."id"

CREATE VIEW users_roles__with_names WITH (security_invoker = true) AS SELECT "users_roles"."id", "users_roles"."user_id", COALESCE(users.name, '[' || users_roles.user_id || ']') AS "user", "users_roles"."role_id", COALESCE(roles.name, '[' || users_roles.role_id || ']') AS "role", "users_roles"."added_on", "users_roles"."added_by_id", COALESCE(added_by_user.name, '[' || users_roles.added_by_id || ']') AS "added_by", "users_roles"."fixed" FROM "users_roles" LEFT JOIN "users" ON "users_roles"."user_id" = "users"."id" LEFT JOIN "roles" ON "users_roles"."role_id" = "roles"."id" LEFT JOIN "users" AS "added_by_user" ON "users_roles"."added_by_id" = "added_by_user"."id"

CREATE VIEW sessions__with_names WITH (security_invoker = true) AS SELECT "sessions".*, "users"."name" AS "user_name" FROM "sessions" JOIN "users" ON "sessions"."user_id" = "users"."id"

